INSERT INTO cities (name, slug, region, short_description, long_description, image_url, lat, lng) VALUES
('Brač', 'brac', 'Dalmatia', $string$The island of Zlatni Rat, the golden horn beach that graces every Croatian postcard.$string$, $string$Brač is the largest Dalmatian island, famous for its white limestone (used to build Diocletian's Palace) and the iconic Zlatni Rat beach near Bol. Beyond the beach, Brač offers stone villages, olive groves, hidden coves, and the blustery Vidova Gora — the highest peak in the Adriatic islands. A day-trip from Split, a week-long escape from everything else.$string$, 'https://images.pexels.com/photos/27651506/pexels-photo-27651506.jpeg?auto=compress&cs=tinysrgb&w=1200', 43.3333, 16.5500),
('Krk', 'krk', 'Kvarner', $string$The golden island — Croatian wine, Vrbnik cliffs, and Baška's sweeping beach.$string$, $string$Krk is the largest island in the Adriatic (depending on the tide), connected to the mainland by a dramatic bridge. Krk Town offers Roman ruins and medieval walls, Vrbnik perches on a vertical cliff with the narrowest street in the world, and Baška beach is a crescent of golden pebble. The island is also the cradle of Croatian Glagolitic script — centuries of letters carved into stone.$string$, 'https://images.pexels.com/photos/20253290/pexels-photo-20253290.jpeg?auto=compress&cs=tinysrgb&w=1200', 45.0583, 14.5667),
('Pag', 'pag', 'Kvarner', $string$The moon island — Pag lace, salt pans, and the sharpest cheese in Croatia.$string$, $string$Pag looks like another planet: a barren karst landscape the wind has scraped to white stone. Pag Town is a Renaissance masterpiece of grid streets; Novalja and Zrće Beach host Croatia's biggest summer parties. But the island's quieter magic is its lace, its salt, and the hard paški sir cheese made from sheep grazed on wild sage.$string$, 'https://images.pexels.com/photos/5457972/pexels-photo-5457972.jpeg?auto=compress&cs=tinysrgb&w=1200', 44.4419, 15.0517),
('Lošinj', 'losinj', 'Kvarner', $string$The island of vitality — fragrant pines, dolphins, and the cleanest air in the Adriatic.$string$, $string$Lošinj is the fragrant island — pine forests, eucalyptus, and the cleanest air in the Mediterranean. Mali and Veli Lošinj are elegant 19th-century spa towns; the surrounding sea is home to a resident pod of dolphins; Čikat Bay is a long ribbon of pine-backed beach. The island has been a wellness destination for 130 years and remains one of the most restorative places on the Croatian coast.$string$, 'https://images.pexels.com/photos/14992419/pexels-photo-14992419.jpeg?auto=compress&cs=tinysrgb&w=1200', 44.5186, 14.4664),
('Rab', 'rab', 'Kvarner', $string$Four bell towers, sandy beaches, and a medieval old town on the sea.$string$, $string$Rab Town is one of the prettiest in the Adriatic — four campaniles rising above a compact medieval town built on a narrow peninsula. The Lopar peninsula to the north has the rarest thing in Croatia — sandy beaches, including the famous Paradise Beach. Rab was a tourist destination in the Roman era; it has been a holiday island ever since.$string$, 'https://images.pexels.com/photos/13125481/pexels-photo-13125481.jpeg?auto=compress&cs=tinysrgb&w=1200', 44.7500, 14.4500),
('Mljet', 'mljet', 'Dalmatia', $string$The greenest island — salt lakes in a national park, Odysseus country, and pine to the waterline.$string$, $string$Mljet is the most heavily-forested island in the Adriatic, its western third a national park built around two saltwater lakes. Odysseus is said to have been shipwrecked here and stayed seven years. Hire a bike, swim in the Veliko Jezero, paddle to the island-within-an-island of Sveta Marija, and you may do the same.$string$, 'https://images.pexels.com/photos/30492414/pexels-photo-30492414.jpeg?auto=compress&cs=tinysrgb&w=1200', 42.7500, 17.5667)
